// EDIT THESE: what you sell, where, and where the alert goes.
return [{ json: {
  email: 'you@example.com',          // the weekly alert goes here
  keywords: ['software', 'cloud'],   // words to find in notices (any language for EU notices)
  euCountries: ['IE', 'DE', 'NL'],   // EU buyer countries (two-letter codes); [] for all of Europe
  cpvCodes: ['72'],                  // CPV prefixes, e.g. 72 IT services, 79 business services; [] for any
  minValue: 0,                       // minimum stated value (notice currency); 0 keeps notices without a value
  days: 7,                           // look-back window in days
  closingSoonDays: 14                // tenders closing within this many days are flagged
} }];

// Merge EU and UK notices, drop ones already sent, flag the ones closing soon, sort by deadline.
const all = n => { try { return $(n).all().map(i => i.json); } catch { return []; } };
const s = $('Your settings').first().json;
const sent = new Set(all('Read sent tenders').map(r => String(r.Link || '').trim()).filter(Boolean));
const today = new Date(); today.setUTCHours(0, 0, 0, 0);
const daysLeft = d => (d ? Math.round((Date.parse(String(d).slice(0, 10)) - today) / 864e5) : null);
const rows = [];
const errors = [];
for (const r of all('EU tenders (TED)')) {
  if (!r.noticeUrl) { if (r.error) errors.push('EU: ' + r.error); continue; }
  rows.push({ Source: 'EU (TED)', Country: r.buyerCountry || '', Title: r.title || '', Buyer: r.buyer || '', Value: r.value ?? '', Currency: r.currency || '', Deadline: r.deadline || '', Published: r.publishedOn || '', CPV: (r.cpvCodes || []).slice(0, 3).join(' '), Link: r.noticeUrl });
}
for (const r of all('UK tenders')) {
  if (!r.noticeUrl) { if (r.error) errors.push('UK: ' + r.error); continue; }
  rows.push({ Source: r.source || 'UK', Country: 'GBR', Title: r.title || '', Buyer: r.buyer || '', Value: r.value ?? '', Currency: r.currency || 'GBP', Deadline: String(r.deadline || '').slice(0, 10), Published: String(r.publishedAt || '').slice(0, 10), CPV: (r.cpvCodes || []).slice(0, 3).join(' '), Link: r.noticeUrl });
}
const fresh = [...new Map(rows.filter(r => !sent.has(r.Link)).map(r => [r.Link, r])).values()]
  .map(r => { const d = daysLeft(r.Deadline); return { ...r, 'Days left': d ?? '', 'Closing soon': d != null && d >= 0 && d <= s.closingSoonDays ? 'yes' : '', 'Sent on': today.toISOString().slice(0, 10) }; })
  .sort((a, b) => (a['Days left'] === '' ? 1e9 : a['Days left']) - (b['Days left'] === '' ? 1e9 : b['Days left']));
if (!fresh.length) return [{ json: { _none: true, errors } }];
return fresh.map(r => ({ json: { ...r, _errors: errors } }));

// One HTML email: closing soon first, then everything else new this week.
const rows = $input.all().map(i => i.json).filter(r => !r._none);
const errors = ($input.first().json._errors || $input.first().json.errors || []);
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = r => (r.Value === '' || r.Value == null ? 'value not stated' : Number(r.Value).toLocaleString('en-GB') + ' ' + esc(r.Currency));
const line = r => `<li><a href="${esc(r.Link)}">${esc(r.Title)}</a><br><span style="color:#555">${esc(r.Buyer)} (${esc(r.Country)}) &middot; ${money(r)} &middot; deadline ${esc(r.Deadline || 'not stated')}${r['Days left'] !== '' ? ` (${r['Days left']} days)` : ''} &middot; ${esc(r.Source)}</span></li>`;
const soon = rows.filter(r => r['Closing soon']);
const rest = rows.filter(r => !r['Closing soon']);
const s = $('Your settings').first().json;
const head = `<p>${rows.length} new public tenders matching <b>${esc(s.keywords.join(', '))}</b> in the last ${s.days} days.</p>`;
const foot = `<p style="color:#666;font-size:12px">${errors.length ? 'Notes: ' + esc(errors.join(' ')) + '<br>' : ''}Data: EU Tenders Scraper (TED) and UK Government Tenders Scraper by Pagecraft on Apify. Already-sent tenders are skipped using your Google Sheet.</p>`;
return [{ json: {
  count: rows.length,
  subject: rows.length ? `Tender alert: ${rows.length} new (${soon.length} closing soon)` : 'Tender alert: nothing new this week',
  html: head + (soon.length ? `<h3>Closing soon</h3><ul>${soon.map(line).join('')}</ul>` : '') + (rest.length ? `<h3>New this week</h3><ul>${rest.map(line).join('')}</ul>` : '') + foot
} }];
